/*
 * Cogito local htmx-compatible runtime.
 * Implements the progressively enhanced request features used by the Console.
 * No network dependency or dynamic code loading.
 */
(function (global) {
  "use strict";

  function emit(element, name, detail) {
    element.dispatchEvent(
      new CustomEvent(name, { bubbles: true, cancelable: true, detail: detail || {} })
    );
  }

  function targetFor(element) {
    var selector = element.getAttribute("hx-target");
    return selector ? document.querySelector(selector) : element;
  }

  function indicatorFor(element) {
    var selector = element.getAttribute("hx-indicator");
    return selector ? document.querySelector(selector) : null;
  }

  function requestHeaders(element) {
    var headers = Object.assign({}, htmx.config.headers);
    headers["HX-Request"] = "true";
    headers["HX-Current-URL"] = global.location.href;
    if (element.id) headers["HX-Trigger"] = element.id;
    var target = targetFor(element);
    if (target && target.id) headers["HX-Target"] = target.id;
    return headers;
  }

  function requestBody(element, method) {
    if (method === "GET") return null;
    var form = element.tagName === "FORM" ? element : element.closest("form");
    return form ? new FormData(form) : null;
  }

  function applySwap(target, html, mode) {
    if (!target) return;
    if (mode === "outerHTML") target.outerHTML = html;
    else if (mode === "beforeend") target.insertAdjacentHTML("beforeend", html);
    else if (mode === "afterbegin") target.insertAdjacentHTML("afterbegin", html);
    else target.innerHTML = html;
  }

  async function issue(element, method, url) {
    var target = targetFor(element);
    var indicator = indicatorFor(element);
    var detail = { elt: element, target: target };
    emit(element, "htmx:beforeRequest", detail);
    element.classList.add("htmx-request");
    if (indicator) indicator.classList.add("htmx-request");
    try {
      var response = await fetch(url, {
        method: method,
        headers: requestHeaders(element),
        body: requestBody(element, method),
        credentials: "same-origin",
      });
      detail.xhr = response;
      if (!response.ok) {
        emit(element, "htmx:responseError", detail);
        return;
      }
      var html = await response.text();
      applySwap(target, html, element.getAttribute("hx-swap") || "innerHTML");
      if (target) htmx.process(target);
      emit(element, "htmx:afterSwap", detail);
    } catch (error) {
      detail.error = error;
      emit(element, "htmx:sendError", detail);
    } finally {
      element.classList.remove("htmx-request");
      if (indicator) indicator.classList.remove("htmx-request");
      emit(element, "htmx:afterRequest", detail);
    }
  }

  function bind(element) {
    if (element.dataset.cogitoHtmxBound === "true") return;
    var getUrl = element.getAttribute("hx-get");
    var postUrl = element.getAttribute("hx-post");
    if (!getUrl && !postUrl) return;
    element.dataset.cogitoHtmxBound = "true";
    var eventName = element.tagName === "FORM" ? "submit" : "click";
    element.addEventListener(eventName, function (event) {
      event.preventDefault();
      void issue(element, postUrl ? "POST" : "GET", postUrl || getUrl);
    });
  }

  var htmx = {
    version: "2.0.4-compat",
    config: { headers: {} },
    process: function (root) {
      var scope = root || document;
      if (scope.matches && (scope.matches("[hx-get]") || scope.matches("[hx-post]"))) {
        bind(scope);
      }
      scope.querySelectorAll("[hx-get], [hx-post]").forEach(bind);
    },
    trigger: function (element, name, detail) {
      emit(element, name, detail);
    },
  };

  global.htmx = htmx;
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () {
      htmx.process(document);
    });
  } else {
    htmx.process(document);
  }
})(globalThis);
